code.cpp:
class Solution {
public:
    vector<int> separateDigits(vector<int>& nums) {
        vector<int> ans;
        ans.reserve(nums.size() * 6);
        for (int x : nums) {
            int p = 1;
            while (p * 10 <= x) {
                p *= 10;
            }
            while (p > 0) {
                ans.push_back(x / p);
                x %= p;
                p /= 10;
            }
        }
        return ans;
    }
};
